import warnings

__doc__ = """
Library module description

I thought about library objects but now I prefer the idea of LibraryManagers.
Python Libraries can have their own library manager but the actual libraries
(the imported stuff) are not represented by it, that's why 'Library' would be 
misleading.
"""


class LibraryManager:
    """
    Library manager class description.

    Used to create, manage, adapt and compile libraries.
    """

    _FILEENDING = "txt"
    _INDENTSTR = "  "

    def __init__(self, libname):
        self._libname = libname
        self._fileinfo = {
            "basepath": ".",
            "filename": f"{self.name}.{self.fileending}",
        }
        self._meta = {
            "library_name": f"{self.name}",
        }
        self._status = {
            "created": False,
            "compiled": False,
        }
        self._dependencies = {}
        self._libroutines = {}

    @property
    def fileending(self):
        """file type ending"""
        return self._FILEENDING

    @property
    def name(self):
        """read-only access to property name"""
        return self._libname

    @property
    def libroutines(self):
        """generator-access to libroutines"""
        yield from self._libroutines.items()

    def append(
        self, routine, implementation="default", exception_existing=False
    ):
        """append a routine to the library"""
        libroutine = self.from_routine(routine, implementation=implementation)
        ident_impl = (libroutine.identifier, libroutine.implementation)
        if ident_impl in self._libroutines:
            if exception_existing:
                raise KeyError(
                    f"Routine '{libroutine.name}' already exists in library"
                )

            warnings.warn(
                f"Routine '{libroutine.name}' already exists in library"
            )
            return
        self._libroutines[ident_impl] = libroutine

    def __getitem__(self, key):
        identififer, implementation = key
        return self._libroutines.get((identififer, implementation))

    def from_routine(self, routine, implementation=None):
        """create a libroutine from the routine"""
        raise NotImplementedError(
            "'to_libroutine' must be implemented by subclasses"
        )

    def compile(self):
        """compile the library"""
        if not self._status["created"]:
            self.create()
        # compile dependencies, then compile self.
        # finally:
        self._status["ready"] = True

    def create(self):
        """create the library, i.e. write to file(s)"""
        # create dependencies,
        # then create self.
        # finally:
        self._status["created"] = True

    def _get_library_head_lines(self, **_kwargs):
        return
        yield

    def _get_library_deps_lines(self, **_kwargs):
        return
        yield

    def _get_library_const_lines(self, **_kwargs):
        return
        yield

    def _get_library_routine_lines(self, **_kwargs):
        return
        yield

    def _get_library_foot_lines(self, **_kwargs):
        return
        yield

    def create_source_lines(self, **kwargs):
        """create the source code lines"""
        yield from self._get_library_head_lines(**kwargs)
        yield from self._get_library_deps_lines(**kwargs)
        yield from self._get_library_const_lines(**kwargs)
        yield from self._get_library_routine_lines(**kwargs)
        yield from self._get_library_foot_lines(**kwargs)

    def get_meta(self, key=None):
        """return meta information on the library"""
        if key is None:
            return dict(self._meta)
        return self._meta.get(key)

    def _collect_dependencies(self):
        dependencies = {}
        for _, libroutine in self._libroutines.items():
            for _, dep in libroutine.dependencies:
                if dep.library.name not in dependencies:
                    dependencies[dep.library.name] = (dep.library, [dep])
                else:
                    dependencies[dep.library.name][1].append(dep)
        return dependencies


"""
NAMING SCHEME
=============

backends/lib/backend_[backend_specifier]_[implementation].[ending]
e.g.: backend_f90_base.f90, backend_cuda_poly.cu, ...


first to be implemented
-------------------------

linear: one instruction: one scale for one x_i
y_j <- a * x_i

multilinear: one instruction: one scale for one x_i
z_l <- a * x_i * y_j

subroutinecall: call another subroutine
name(*params)


later to be implemted
---------------------

special function: sin, cos, exp, log, snh, csh
sfun_sin y_j <- a_i * [sin, cos, ...](b_i * x_i) + c_i

bivariate multinomial: one instruction <-> combined powers of multiple x_i
z_l <- a_1 x_i,1 ** n_1,1 * x_i,2 ** n_1,2 * ... y_i,1 ** m_1,1 * ... + 

multinomial: one instruction <-> combined powers of multiple x_i
y_j <- a_1 x_i,1 ** n_1,1 * x_i,2 ** n_1,2 * ... + 

polynomial: one instruction <-> powers of one x_i
y_j <- a_1 x_i ** n_1 + ...

monomial: one instruction <-> one power of one x_i
y_j <- a x_i ** n

affine (linear plus a constant): one instruction: one scaled x_i and one offset b
y_j <- a x_i + b

lookup: one instruction: one specific x_i
y_j <- x_i

mask: one instruction: one specific x_i
y_i <- x_i with extras

permutation: one instruction: a pair of i and j, where i is mapped to j
y_j <- x_i with extras


"""


